{
  "slots": {
    "fuel_phase": {
      "value": "mixed",
      "quote": "These tests will involve gaseous, liquid, and solid fuels."
    },
    "gravity": {
      "value": "several levels",
      "quote": "Additionally, preliminary flight tests will be performed to verify the experiment operations and for comparison with ground-based tests."
    },
    "flow": {
      "value": "quiescent",
      "quote": "The BRE flight program seeks to establish the burning conditions in a quiescent microgravity ambient in terms of material properties."
    },
    "atmosphere": {
      "value": "varied",
      "quote": "Consider O2/N2 ambients with various pressures and ambient O2 concentrations and pressures. NASA - considered atmosphere for human space missions will be examined: 14.7 psia, 21 % oxygen: 10.2 psia, 26.5 %; and 8.2 psia, 34 % oxygen."
    }
  },
  "functions": [
    {
      "function": "material flammability",
      "statement": "The investigation contributes to material flammability by enabling the Cone Calorimeter test as a basis for establishing flammability maps for real materials.",
      "quote": "This could enable the Cone Calorimeter (NASA Test 2) test as a basis for establishing flammability maps for real materials."
    },
    {
      "function": "ignition",
      "statement": "The investigation explores ignition limits under normal gravity because these results are expected to carry over to microgravity conditions.",
      "quote": "Ignition limit tests are not proposed for microgravity, but we will explore these under normal gravity. We believe there is better control on Earth-based ignition testing and that these results should carry over to microgravity conditions."
    },
    {
      "function": "extinction",
      "statement": "The investigation determines extinction limits by reducing the fuel flow in small increments after the burner temperature has steadied.",
      "quote": "The extinction limit could be found once the burner temperature has steadied, and the heat flux sensor has not exceeded its limit. At that state, the flow rate can be reduced in small increments, until extinction is observed and the flow rate shut off."
    },
    {
      "function": "soot and smoke",
      "statement": "The investigation evaluates smoke point as a fuel property to help determine burning conditions that represent real solid or liquid fuels.",
      "quote": "It is hypothesized that BRE can determine a range of burning conditions in microgravity as a function of heat of gasification, reradiation heat flux, applied radiant heat flux, heat of combustion and smoke point."
    }
  ],
  "statements": [
    {
      "statement": "The flight experiments use methane/nitrogen and ethylene/nitrogen mixtures supplied through porous circular burners of 25 mm and 50 mm diameter.",
      "quote": "Observe burning behavior in long-duration microgravity for CH4/N2 and C2H4/N2mixtures on porous circular burners of 25  and 50 mm diameter."
    },
    {
      "statement": "Burner surface temperature and heat flux are monitored to observe a broad range of burning conditions during a single test.",
      "quote": "Because burner surface temperature and heat flux will vary, this will allow a broad range of conditions to be observed during a single test."
    },
    {
      "statement": "Quasi-steady burning corresponding to condensed-phase materials such as PMMA and Nylon was observed in microgravity despite the absence of air flow.",
      "quote": "Quasi-steady burning corresponding to various condensed-phase materials (such as PMMA and Nylon) was observed in microgravity despite the absence of air flow"
    },
    {
      "statement": "Combustion persisted in elevated-oxygen atmospheres being considered for future spacecraft, whereas similar flames self-extinguished in a normal 21% oxygen atmosphere.",
      "quote": "The ongoing combustion without air flow was notably seen in elevated-oxygen atmospheres which are being considered for use in future spacecraft, whereas such flames in a normal atmosphere of 21% oxygen self-extinguished in a short time."
    },
    {
      "statement": "A test terminates when the flame extinguishes, the burner surface temperature equilibrates, or the heat flux sensor nears its temperature limit.",
      "quote": "Eventually either the flame will extinguish, the surface temperature of the burner will equilibrate, or the temperature limit of the heat flux sensor will be reached."
    }
  ]
}
